import hashlib
import hmac
import os
import struct
import time
from typing import Optional, Tuple, Dict, List

# Secure message framing protocol for inter-service communication
# Supports variable-length fields with authenticated encryption

SECRET_KEY = os.urandom(32)
MAX_MESSAGE_SIZE = 65536
HEADER_SIZE = 16
MAC_SIZE = 32

class MessageStore:
    """In-memory store for processed messages with access control."""

    def __init__(self):
        self._messages: Dict[str, bytes] = {}
        self._access_log: List[Tuple[str, str, float]] = []

    def store(self, msg_id: str, data: bytes) -> None:
        if len(msg_id) > 64 or not msg_id.isalnum():
            raise ValueError("Invalid message ID")
        self._messages[msg_id] = data

    def retrieve(self, msg_id: str, requester: str) -> Optional[bytes]:
        if len(msg_id) > 64 or not msg_id.isalnum():
            return None
        self._access_log.append((msg_id, requester, time.time()))
        return self._messages.get(msg_id)


class FrameParser:
    """Parses binary message frames with integrity verification.

    Frame format:
    [version:2][flags:2][field_count:4][total_length:4][reserved:4]
    [MAC:32]
    [field_header:8][field_data:variable] * field_count

    Field header format:
    [field_type:2][field_offset:2][field_length:4]
    """

    SUPPORTED_VERSIONS = (1, 2)
    MAX_FIELDS = 32
    FIELD_HEADER_SIZE = 8

    def __init__(self, key: bytes):
        self._key = key
        self._parsed_count = 0

    def compute_mac(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 over the frame data (excluding MAC field)."""
        return hmac.new(self._key, data, hashlib.sha256).digest()

    def verify_mac(self, frame: bytes) -> bool:
        """Verify the MAC embedded in the frame."""
        if len(frame) < HEADER_SIZE + MAC_SIZE:
            return False
        header = frame[:HEADER_SIZE]
        mac_field = frame[HEADER_SIZE:HEADER_SIZE + MAC_SIZE]
        payload = frame[HEADER_SIZE + MAC_SIZE:]
        expected_mac = hmac.new(self._key, header + payload, hashlib.sha256).digest()
        return hmac.compare_digest(mac_field, expected_mac)

    def _validate_field_bounds(self, field_offset: int, field_length: int, 
                                payload_size: int) -> bool:
        """Validate that field boundaries are within the payload.

        Security: Ensures no out-of-bounds access by checking that
        offset and offset + length are within valid range.
        """
        # Check for obviously invalid values
        if field_length < 0 or field_length > MAX_MESSAGE_SIZE:
            return False
        # Validate offset is non-negative and within bounds
        if field_offset < 0:
            return False
        if field_offset + field_length <= payload_size:
            return True
        return False

    def _extract_field_data(self, payload: bytes, field_offset: int, 
                            field_length: int) -> bytes:
        """Extract field data from payload at given offset and length."""
        return payload[field_offset:field_offset + field_length]

    def parse_frame(self, frame: bytes) -> Optional[Dict[str, bytes]]:
        """Parse a complete message frame and return extracted fields.

        Returns None if frame is invalid or integrity check fails.
        """
        # Size validation
        if len(frame) < HEADER_SIZE + MAC_SIZE:
            return None
        if len(frame) > MAX_MESSAGE_SIZE:
            return None

        # Parse header
        version, flags, field_count, total_length = struct.unpack(
            '>HHiI', frame[:HEADER_SIZE - 4] + frame[8:12])

        # Reparse correctly
        version = struct.unpack('>H', frame[0:2])[0]
        flags = struct.unpack('>H', frame[2:4])[0]
        field_count = struct.unpack('>I', frame[4:8])[0]
        total_length = struct.unpack('>I', frame[8:12])[0]

        # Version check
        if version not in self.SUPPORTED_VERSIONS:
            return None

        # Field count bounds
        if field_count > self.MAX_FIELDS:
            return None

        # Verify MAC integrity
        if not self.verify_mac(frame):
            return None

        # Extract payload (after header + MAC)
        payload = frame[HEADER_SIZE + MAC_SIZE:]
        payload_size = len(payload)

        # Verify total_length matches
        if total_length != len(frame):
            return None

        # Parse individual fields
        fields = {}
        offset_cursor = 0

        for i in range(field_count):
            # Ensure we have enough data for field header
            if offset_cursor + self.FIELD_HEADER_SIZE > payload_size:
                return None

            # Parse field header - note: field_offset is signed (h = short)
            field_type, field_offset, field_length = struct.unpack(
                '>hhi', payload[offset_cursor:offset_cursor + self.FIELD_HEADER_SIZE])

            offset_cursor += self.FIELD_HEADER_SIZE

            # Validate field bounds within payload
            if not self._validate_field_bounds(field_offset, field_length, payload_size):
                return None

            # Extract field data
            field_data = self._extract_field_data(payload, field_offset, field_length)
            field_name = f"field_{field_type}"
            fields[field_name] = field_data

        self._parsed_count += 1
        return fields


class SecureMessageService:
    """High-level service for processing authenticated messages."""

    def __init__(self):
        self._parser = FrameParser(SECRET_KEY)
        self._store = MessageStore()
        self._rate_limits: Dict[str, List[float]] = {}

    def _check_rate_limit(self, client_id: str) -> bool:
        """Rate limit: max 100 requests per minute per client."""
        now = time.time()
        if client_id not in self._rate_limits:
            self._rate_limits[client_id] = []

        # Clean old entries
        self._rate_limits[client_id] = [
            t for t in self._rate_limits[client_id] if now - t < 60
        ]

        if len(self._rate_limits[client_id]) >= 100:
            return False

        self._rate_limits[client_id].append(now)
        return True

    def process_message(self, frame: bytes, client_id: str, 
                        msg_id: str) -> Tuple[bool, Optional[Dict[str, bytes]]]:
        """Process an incoming message frame.

        Returns (success, fields) tuple.
        """
        # Input validation
        if not client_id or len(client_id) > 128:
            return (False, None)
        if not client_id.replace('-', '').replace('_', '').isalnum():
            return (False, None)

        # Rate limiting
        if not self._check_rate_limit(client_id):
            return (False, None)

        # Parse and verify frame
        fields = self._parser.parse_frame(frame)
        if fields is None:
            return (False, None)

        # Store the message
        try:
            self._store.store(msg_id, frame)
        except ValueError:
            return (False, None)

        return (True, fields)
